import os, json, time, csv
import numpy as np

N = 26
R_MIN = 1e-6
SAFETY = 1e-9
TOL_EQ = 1e-8

P_CENTERS = 'storage/noesis/latest_centers.txt'
P_RADII   = 'storage/noesis/latest_radii.txt'
P_SHADOWS = 'storage/noesis/exports/shadow_prices_tol1e8.csv'
OUT_DIR   = 'storage/noesis/exports'
OUT_JSON  = os.path.join(OUT_DIR, 'operator_gate_report_latest.json')
OUT_TOP   = os.path.join(OUT_DIR, 'operator_top_pairs_latest.json')
OUT_QUADS = os.path.join(OUT_DIR, 'operator_quad_candidates_latest.json')

def _ensure_dir(p):
    os.makedirs(p, exist_ok=True)

def _load_snapshot():
    try:
        c = np.loadtxt(P_CENTERS, dtype=float).reshape(N, 2)
        r = np.loadtxt(P_RADII, dtype=float).reshape(N,)
        if np.any(r <= 0): raise ValueError("non-positive r")
        return c, r
    except Exception:
        # conservative fallback
        centers = []
        radius = 0.08
        for i in range(5):
            for j in range(6):
                if len(centers) < N:
                    x = 0.1 + i * 0.2
                    y = 0.1 + j * 0.15
                    centers.append([x, y])
        c = np.array(centers, dtype=float)
        r = np.full(N, radius, dtype=float)
        return c, r

def _final_shrink(c, r, eps=SAFETY):
    return c, np.maximum(r - eps, R_MIN)

def boundary_active(c, r, tol=TOL_EQ):
    x = c[:, 0]; y = c[:, 1]
    act = (x - r <= tol) | (1.0 - x - r <= tol) | (y - r <= tol) | (1.0 - y - r <= tol)
    return act

def read_shadow_prices_csv(path):
    rows = []
    if not os.path.exists(path):
        return rows
    with open(path, 'r', newline='') as f:
        reader = csv.DictReader(f)
        hdr = [h.lower() for h in reader.fieldnames]
        def pick(colnames):
            for name in colnames:
                if name in hdr:
                    return hdr.index(name)
            return None
        idx_i  = pick(['i','idx_i','disc_i'])
        idx_j  = pick(['j','idx_j','disc_j'])
        idx_la = pick(['lambda','lambda_est','multiplier','shadow_price'])
        idx_sl = pick(['slack','pair_slack'])
        for row in reader:
            try:
                def at(row, k):
                    if isinstance(k, int):
                        key = reader.fieldnames[k]
                        return row[key]
                    return None
                i  = int(float(at(row, idx_i)))  if idx_i  is not None else None
                j  = int(float(at(row, idx_j)))  if idx_j  is not None else None
                la = float(at(row, idx_la))      if idx_la is not None else None
                sl = float(at(row, idx_sl))      if idx_sl is not None else np.nan
                if i is None or j is None or la is None:
                    continue
                if not (0 <= i < N and 0 <= j < N and i != j):
                    continue
                rows.append({'i': i, 'j': j, 'lambda': la, 'slack': sl})
            except Exception:
                continue
    rows.sort(key=lambda d: d.get('lambda', -np.inf), reverse=True)
    return rows

def _orient(a, b, c):
    return (b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])

def _on_segment(a, b, c):
    return (min(a[0], b[0]) <= c[0] <= max(a[0], b[0]) and
            min(a[1], b[1]) <= c[1] <= max(a[1], b[1]))

def segments_cross(p1, p2, q1, q2, strict=True):
    o1 = _orient(p1, p2, q1)
    o2 = _orient(p1, p2, q2)
    o3 = _orient(q1, q2, p1)
    o4 = _orient(q1, q2, p2)
    if strict:
        return (o1*o2 < 0) and (o3*o4 < 0)
    if o1 == 0 and _on_segment(p1, p2, q1): return True
    if o2 == 0 and _on_segment(p1, p2, q2): return True
    if o3 == 0 and _on_segment(q1, q2, p1): return True
    if o4 == 0 and _on_segment(q1, q2, p2): return True
    return (o1*o2 < 0) and (o3*o4 < 0)

def detect_crossing_motif(c, r, top_pairs, k=15, tol=TOL_EQ):
    act_b = boundary_active(c, r, tol=tol)
    cand_pairs = []
    for d in top_pairs[:max(0, k)]:
        i, j = d['i'], d['j']
        if act_b[i] or act_b[j]:
            continue
        cand_pairs.append((i, j, float(d.get('lambda', 0.0)), float(d.get('slack', np.nan))))
    quads = []
    m = len(cand_pairs)
    for a in range(m):
        i, j, _, _ = cand_pairs[a]
        pi, pj = c[i], c[j]
        for b in range(a+1, m):
            k_, l, _, _ = cand_pairs[b]
            if len({i, j, k_, l}) < 4:
                continue
            pk, pl = c[k_], c[l]
            if segments_cross(pi, pj, pk, pl, strict=True):
                quads.append({'quad': [i, j, k_, l]})
    has = len(quads) > 0
    top_dump = [{'i': int(i), 'j': int(j), 'lambda': float(la), 'slack': (None if np.isnan(sl) else float(sl))}
                for (i, j, la, sl) in cand_pairs]
    return has, quads, top_dump

def _write_json(path, obj):
    _ensure_dir(os.path.dirname(path))
    with open(path, 'w') as f:
        json.dump(obj, f, indent=2)

def construct_packing():
    c, r = _load_snapshot()
    c, r = _final_shrink(c, r, eps=SAFETY)
    try:
        top = read_shadow_prices_csv(P_SHADOWS)
        has, quads, top_dump = detect_crossing_motif(c, r, top, k=15, tol=TOL_EQ)
        report = {
            'generated_at': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()),
            'tol_pairs': TOL_EQ,
            'k_pairs': 15,
            'has_candidate': bool(has),
            'num_candidates': int(len(quads)),
            'example_quads': quads[:5]
        }
        _write_json(OUT_JSON, report)
        _write_json(OUT_TOP, {'top_pairs': top_dump})
        _write_json(OUT_QUADS, {'quad_candidates': quads})
    except Exception as e:
        _write_json(OUT_JSON, {
            'generated_at': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()),
            'error': str(e),
            'has_candidate': False,
            'num_candidates': 0
        })
    return c.astype(float), r.astype(float)
